#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node* next;
    struct Node* prev;
};

// Create first node only
struct Node* create(int value) {
    struct Node* head = (struct Node*)malloc(sizeof(struct Node));
    head->data = value;
    head->next = NULL;
    head->prev = NULL;
    return head;
}

// Insert at beginning
struct Node* insertAtBeginning(struct Node* head, int value) {
    if (head == NULL)
        return create(value);

    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = value;
    newNode->prev = NULL;
    newNode->next = head;
    head->prev = newNode;
    head = newNode;

    return head;
}

// Insert at end
struct Node* insertAtEnd(struct Node* head, int value) {
    if (head == NULL)
        return create(value);

    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = value;
    newNode->next = NULL;

    struct Node* temp = head;
    while (temp->next != NULL)
        temp = temp->next;

    temp->next = newNode;
    newNode->prev = temp;

    return head;
}

// Insert at specific position (1-based)
struct Node* insertAtPosition(struct Node* head, int value, int pos) {
    if (head == NULL || pos == 1)
        return insertAtBeginning(head, value);

    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = value;

    struct Node* temp = head;
    for (int i = 1; i < pos - 1 && temp->next != NULL; i++)
        temp = temp->next;

    newNode->next = temp->next;
    newNode->prev = temp;

    if (temp->next != NULL)
        temp->next->prev = newNode;

    temp->next = newNode;

    return head;
}

// Delete at beginning
struct Node* deleteAtBeginning(struct Node* head) {
    if (head == NULL)
        return head;

    struct Node* temp = head;
    head = head->next;

    if (head != NULL)
        head->prev = NULL;

    free(temp);
    return head;
}

// Delete at end
struct Node* deleteAtEnd(struct Node* head) {
    if (head == NULL)
        return head;

    if (head->next == NULL) {
        free(head);
        return NULL;
    }

    struct Node* temp = head;
    while (temp->next != NULL)
        temp = temp->next;

    temp->prev->next = NULL;
    free(temp);

    return head;
}

// Delete at a given position
struct Node* deleteAtPosition(struct Node* head, int pos) {
    if (head == NULL)
        return head;

    if (pos == 1)
        return deleteAtBeginning(head);

    struct Node* temp = head;
    for (int i = 1; i < pos && temp != NULL; i++)
        temp = temp->next;

    if (temp == NULL) return head;

    if (temp->next != NULL)
        temp->next->prev = temp->prev;

    temp->prev->next = temp->next;

    free(temp);
    return head;
}

